head.script:
scwin.trigger1_onclick = function(e) {
    grid1.checkAll("chk", "1");
};
scwin.tooltipFormatter = function(rowIndex, colIndex, label) {
    var inputType = grid1.getCellInfo(colIndex).options.inputType;
    label += "_" + inputType + "_custom_tooltip";
    return label;
}
scwin.fireOver = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.mouseOverBehaviour = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireOver(el);
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 style 부분을 확인한다.
    //1. Check the style section in the Source tab.
    //Test step 2. IE 브라우저에서 name1 컬럼에 ... 부분을 마우스 오버한다.
    //2. In the IE browser, mouse over the ... column in the name1 column.
    //Verify step 2. A tooltip is created. (Previous versions did not create a tooltip when that style was applied)
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour($p.id+'grid1_cell_0_2')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_tooltip').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_tooltip').text() == '1111_checkbox_custom_tooltip'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
